#include <QCoreApplication>
#include <QVariantMap>
#include <QTextStream>
#include "DecodeUiFilterPolicy.h"
static bool decodeListModel_isTelemetryOnlyMessage(const QString&s){return s=="TELEMETRY";}
class DecodiumBridge {public:bool m_filtersBypassed=false,m_hideGhostDecodes=false,m_filterCqOnly=false,m_hideTelemetryOnlyDecodes=false;QVariantMap settings;QVariant getSetting(const QString&k,bool d)const{return settings.value(k,d);}bool looksLikeGhostDecode(const QVariantMap&e)const{return e.value("ghost").toBool();}decodium::decode_ui::WorkedFilterOptions workedFilterOptions()const;bool shouldDisplayEntryForBandActivity(const QVariantMap&)const;bool shouldDisplayEntryForBandActivity(const QVariantMap&,const decodium::decode_ui::WorkedFilterOptions&)const;};
#include "bridge_refactor_under_test.inc"
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTextStream o(stdout);DecodiumBridge b;QVariantMap worked{{"dxIsWorkedBand",true},{"isCQ",true},{"dxIsWorked",true},{"message","CQ TEST"}};b.settings["FiltersHideWorkedBand"]=true;o<<"worked|"<<b.shouldDisplayEntryForBandActivity(worked)<<'\n';b.m_filterCqOnly=true;o<<"cq|"<<b.shouldDisplayEntryForBandActivity(worked)<<'\n';b.m_filterCqOnly=false;worked["isTx"]=true;o<<"tx|"<<b.shouldDisplayEntryForBandActivity(worked)<<'\n';worked["isTx"]=false;b.m_filtersBypassed=true;o<<"bypass|"<<b.shouldDisplayEntryForBandActivity(worked)<<'|'<<b.workedFilterOptions().hideWorkedBand<<'\n';b.m_hideGhostDecodes=true;worked["ghost"]=true;o<<"ghost|"<<b.shouldDisplayEntryForBandActivity(worked)<<'\n';b.m_hideGhostDecodes=false;b.m_hideTelemetryOnlyDecodes=true;worked["message"]="TELEMETRY";o<<"telemetry|"<<b.shouldDisplayEntryForBandActivity(worked)<<'\n';worked["displayMessage"]="DISPLAY";o<<"display|"<<b.shouldDisplayEntryForBandActivity(worked)<<'\n';o<<"empty|"<<b.shouldDisplayEntryForBandActivity({})<<'\n';b.m_filtersBypassed=false;b.settings["FiltersWorkedTodayIncludesYesterday"]=true;b.settings["FiltersHideWorkedToday"]=true;QVariantMap y{{"dxIsWorkedYesterday",true}};o<<"yesterday|"<<b.shouldDisplayEntryForBandActivity(y)<<'\n';}
